const ALL = ['2026Instock','Animal','Balustrade','Bathtub','Bench','BookMatchedSlabs','Carving','Columns','DoorSurround','Exterior-Wall-Decoration','Fireplace','Fountain','Lamppost','Marble+ Basin','Marble+ ConsoleTable','MarbleMedallion','MarbleRangeHood','MarbleSlab','Moulding','OutdoorCornice','Planter','Sink','Stairs','Statue','StoneMosaicTile','Table','Vanity','Wainscoting','Wall-Coverings','WindowSurround'];
const wanted = String($('Config').first().json.sheets || '').split(',').map(s => s.trim()).filter(Boolean);
return ALL.filter(s => !wanted.length || wanted.includes(s)).map(sheet_name => ({ json: { sheet_name } }));

// Which columns are needed: Product No., the Shopify admin link and IMAGE URL1 to IMAGE URL11.
const DOC = '1ITSJNL7iql08AklUOLI1QSpOO0HlYEb8Dui0eNBXSeI';
const SHEET = $('Loop Through Sheets').first().json.sheet_name;
const headers = ($input.first().json.values?.[0] || []).map(h => String(h ?? '').trim());
const NEEDED = ['Product No.', 'Shopify_Update_product_URL'].concat(Array.from({ length: 11 }, (_, i) => 'IMAGE URL' + (i + 1)));
const letters = (n) => { let s = ''; n += 1; while (n > 0) { const m = (n - 1) % 26; s = String.fromCharCode(65 + m) + s; n = Math.floor((n - 1) / 26); } return s; };
const q = (s) => `'${String(s).replace(/'/g, "''")}'`;
const cols = NEEDED.map(name => ({ name, idx: headers.lastIndexOf(name) })).filter(c => c.idx >= 0);
const ranges = cols.length ? cols.map(c => `${q(SHEET)}!${letters(c.idx)}3:${letters(c.idx)}`) : [`${q(SHEET)}!A2:A2`];
const url = `https://sheets.googleapis.com/v4/spreadsheets/${DOC}/values:batchGet?majorDimension=COLUMNS&valueRenderOption=FORMATTED_VALUE&` + ranges.map(r => 'ranges=' + encodeURIComponent(r)).join('&');
return [{ json: { sheet_name: SHEET, cols, url, hasUrlCol: cols.some(c => c.name === 'Shopify_Update_product_URL') } }];

// Builds, for each product of the tab, the list of photo files the sheet expects (exact file names, in slot order, exact duplicates dropped).
const plan = $('Plan Columns').first().json;
const vr = $input.first().json.valueRanges || [];
const col = {}; plan.cols.forEach((c, i) => { col[c.name] = vr[i]?.values?.[0] || []; });
const baseUrl = (u) => String(u || '').split('?')[0];
const SHOP_FILES = /(\/s\/files\/1\/0503\/5730\/5497\/files\/|\/cdn\/shop\/files\/)/;
const nameOf = (u) => { const l = baseUrl(u).split('/').pop() || ''; try { return decodeURIComponent(l); } catch (e) { return l; } };
const keyOf = (u) => { const b = baseUrl(u).trim(); return b ? (SHOP_FILES.test(b) ? 'f:' + nameOf(b) : b) : ''; };
const nRows = Math.max(0, ...Object.values(col).map(a => a.length));
const stats = { tab: plan.sheet_name, rows: 0, noShopifyUrl: 0, noImagesInSheet: 0, toCheck: 0 };
const prods = [];
for (let i = 0; i < nRows; i++) {
  const sku = String((col['Product No.'] || [])[i] ?? '').trim();
  const adm = String((col['Shopify_Update_product_URL'] || [])[i] ?? '');
  const m = adm.match(/\/products\/(\d+)/);
  if (!sku && !m) continue;
  stats.rows++;
  if (!m) { stats.noShopifyUrl++; continue; }
  const exp = []; const seen = new Set();
  for (let s = 1; s <= 11; s++) {
    const u = String((col['IMAGE URL' + s] || [])[i] ?? '').trim();
    if (!/^https?:/i.test(u)) continue;
    const k = keyOf(u); if (seen.has(k)) continue; seen.add(k);
    exp.push({ slot: s, key: k, name: nameOf(u) });
  }
  if (!exp.length) { stats.noImagesInSheet++; continue; }
  prods.push({ row: i + 3, sku, id: m[1], exp });
}
stats.toCheck = prods.length;
if (!prods.length) return [{ json: { tab: plan.sheet_name, noProducts: true, stats } }];
const Q = `query Gallery($ids: [ID!]!) { nodes(ids: $ids) { ... on Product { id media(first: 20) { nodes { ... on MediaImage { image { url } } } } } } }`;
const out = [];
for (let i = 0; i < prods.length; i += 8) {
  const chunk = prods.slice(i, i + 8);
  out.push({ json: { tab: plan.sheet_name, stats, chunk, body: { query: Q, variables: { ids: chunk.map(p => 'gid://shopify/Product/' + p.id) } } } });
}
return out;

// Compares each product's gallery on Shopify with the files the sheet expects. Read only.
// Each difference gets a category so the real errors are not buried:
//   cad_missing        only the CAD drawing (slot 11) is missing on the product
//   copies_only        same pictures, but Shopify holds _uuid copies of the sheet files (different file names)
//   order_only         same files, different order
//   check              anything else: wrong/missing/extra files = needs a person
const baseUrl = (u) => String(u || '').split('?')[0];
const SHOP_FILES = /(\/s\/files\/1\/0503\/5730\/5497\/files\/|\/cdn\/shop\/files\/)/;
const nameOf = (u) => { const l = baseUrl(u).split('/').pop() || ''; try { return decodeURIComponent(l); } catch (e) { return l; } };
const keyOf = (u) => { const b = baseUrl(u).trim(); return b ? (SHOP_FILES.test(b) ? 'f:' + nameOf(b) : b) : ''; };
const UUID = /_[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}(?=\.[A-Za-z0-9]+$)/i;
const noUuid = (n) => n.replace(UUID, '');
const reqs = $('Build Products').all().map(i => i.json);
const stats = reqs[0].stats;
const out = [];
const cats = {};
let checked = 0, ok = 0, bad = 0;
const add = (c) => { cats[c] = (cats[c] || 0) + 1; };
$input.all().forEach((it, k) => {
  const rq = reqs[k]; const res = it.json;
  if (!rq) return;
  if (res.error || (res.errors && res.errors.length) || !res.data || !Array.isArray(res.data.nodes)) {
    out.push({ json: { kind: 'error', tab: rq.tab, skus: rq.chunk.map(p => p.sku).join(', '), error: JSON.stringify(res.error || res.errors || res).slice(0, 200) } });
    return;
  }
  rq.chunk.forEach((p, i) => {
    const n = res.data.nodes[i];
    checked++;
    if (!n) { bad++; add('check'); out.push({ json: { kind: 'mismatch', category: 'check', tab: rq.tab, row: p.row, sku: p.sku, productId: p.id, problem: 'product not found on Shopify (deleted or wrong link)' } }); return; }
    const act = (n.media?.nodes || []).filter(m => m && m.image && m.image.url).map(m => ({ key: keyOf(m.image.url), name: nameOf(m.image.url) }));
    const actKeys = act.map(a => a.key), expKeys = p.exp.map(e => e.key);
    // The uuid part of a name is only Shopify's copy id: two names that differ only by it are the same picture.
    const expBase = p.exp.map(e => ({ ...e, base: noUuid(e.name) }));
    const actLeft = act.map(a2 => ({ ...a2, base: noUuid(a2.name) }));
    let paired = 0;
    const missingLeft = [];
    expBase.forEach(e => {
      let j = actLeft.findIndex(x => x.key === e.key);          // exact same file
      if (j >= 0) { actLeft.splice(j, 1); return; }
      j = actLeft.findIndex(x => x.base === e.base);            // same picture, different copy id
      if (j >= 0) { actLeft.splice(j, 1); paired++; return; }
      missingLeft.push(e);
    });
    const missing = missingLeft, extra = actLeft;
    const missCad = missingLeft.filter(m => m.slot === 11), missOther = missingLeft.filter(m => m.slot !== 11);
    // order, comparing with the uuid part ignored
    const e2 = p.exp.map(e => noUuid(e.name)), a2 = act.map(a => noUuid(a.name));
    const common = e2.filter(x => a2.includes(x)), actCommon = a2.filter(x => e2.includes(x));
    const orderOk = JSON.stringify(common) === JSON.stringify(actCommon);
    if (!missing.length && !extra.length && orderOk) { ok++; return; }
    bad++;
    let category = 'check';
    if (!extra.length && !missOther.length) {
      if (missCad.length && orderOk) category = 'cad_missing';
      else if (!missCad.length && orderOk && paired) category = 'copies_only';
      else if (!missCad.length && !orderOk && !paired) category = 'order_only';
    }
    if (category === 'cad_missing' && paired) category = 'cad_missing';
    add(category);
    const problems = [];
    if (missingLeft.length) problems.push('missing on Shopify: ' + missingLeft.map(m => 'slot ' + m.slot + ' ' + m.name).join(', '));
    if (paired) problems.push(paired + ' file(s) are _uuid copies of the sheet files');
    if (extra.length) problems.push('not in the sheet: ' + extra.map(a => a.name).join(', '));
    if (!orderOk) problems.push('order differs from the sheet');
    out.push({ json: { kind: 'mismatch', category, tab: rq.tab, row: p.row, sku: p.sku, productId: p.id, expected: p.exp.length, onShopify: act.length, problem: problems.join(' | ') } });
  });
});
out.push({ json: { kind: 'summary', tab: stats.tab, rows: stats.rows, noShopifyUrl: stats.noShopifyUrl, noImagesInSheet: stats.noImagesInSheet, checked, ok, mismatched: bad, cats } });
return out;

// Last step: totals per tab and per category, and the list of products that need a person (category "check"). Nothing was changed anywhere.
const all = $input.all().map(i => i.json);
const sums = all.filter(j => j.kind === 'summary');
const mism = all.filter(j => j.kind === 'mismatch');
const errs = all.filter(j => j.kind === 'error');
const tot = sums.reduce((a, s) => ({ checked: a.checked + (s.checked || 0), ok: a.ok + (s.ok || 0), mismatched: a.mismatched + (s.mismatched || 0) }), { checked: 0, ok: 0, mismatched: 0 });
const byCategory = {};
mism.forEach(m => { byCategory[m.category] = (byCategory[m.category] || 0) + 1; });
const needsPerson = mism.filter(m => m.category === 'check');
const cap = 150;
return [{ json: {
  readOnly: true, ...tot, errors: errs.length, byCategory,
  meaning: { cad_missing: 'only the CAD drawing (IMAGE URL11) is missing on the product', copies_only: 'same pictures, Shopify holds _uuid copies of the sheet files', order_only: 'same files, different order', check: 'wrong, missing or extra files: needs a person' },
  perTab: sums.map(s => ({ tab: s.tab, checked: s.checked, ok: s.ok, mismatched: s.mismatched, ...s.cats })),
  skuLists: (() => { const o = {}; mism.forEach(m => { if (!m.sku) return; o[m.category] = o[m.category] || {}; o[m.category][m.tab] = (o[m.category][m.tab] ? o[m.category][m.tab] + ',' : '') + m.sku; }); return o; })(),
  orderOnly: mism.filter(m => m.category === 'order_only').map(m => ({ tab: m.tab, row: m.row, sku: m.sku })),
  needsPerson: needsPerson.slice(0, cap).map(m => ({ tab: m.tab, row: m.row, sku: m.sku, expected: m.expected, onShopify: m.onShopify, problem: m.problem })),
  moreNeedsPersonNotShown: Math.max(0, needsPerson.length - cap),
  errorDetails: errs.slice(0, 20)
} }];
